macro_rules! deps {
    () => {
        ByteClasses!();
        StartKind!();
        DFA!();
    };
}

macro_rules! impl_120 {
    () => {
        deps!();
        impl < T : AsRef < [u8] > > DFA < T > { # [doc = " Cheaply return a borrowed version of this sparse DFA. Specifically, the"] # [doc = " DFA returned always uses `&[u8]` for its transitions."] pub fn as_ref < 'a > (& 'a self) -> DFA < & 'a [u8] > { DFA { tt : self . tt . as_ref () , st : self . st . as_ref () , special : self . special , pre : self . pre . clone () , quitset : self . quitset , flags : self . flags , } } # [doc = " Return an owned version of this sparse DFA. Specifically, the DFA"] # [doc = " returned always uses `Vec<u8>` for its transitions."] # [doc = ""] # [doc = " Effectively, this returns a sparse DFA whose transitions live on the"] # [doc = " heap."] # [cfg (feature = "alloc")] pub fn to_owned (& self) -> DFA < alloc :: vec :: Vec < u8 > > { DFA { tt : self . tt . to_owned () , st : self . st . to_owned () , special : self . special , pre : self . pre . clone () , quitset : self . quitset , flags : self . flags , } } # [doc = " Returns the starting state configuration for this DFA."] # [doc = ""] # [doc = " The default is [`StartKind::Both`], which means the DFA supports both"] # [doc = " unanchored and anchored searches. However, this can generally lead to"] # [doc = " bigger DFAs. Therefore, a DFA might be compiled with support for just"] # [doc = " unanchored or anchored searches. In that case, running a search with"] # [doc = " an unsupported configuration will panic."] pub fn start_kind (& self) -> StartKind { self . st . kind } # [doc = " Returns true only if this DFA has starting states for each pattern."] # [doc = ""] # [doc = " When a DFA has starting states for each pattern, then a search with the"] # [doc = " DFA can be configured to only look for anchored matches of a specific"] # [doc = " pattern. Specifically, APIs like [`Automaton::try_search_fwd`] can"] # [doc = " accept a [`Anchored::Pattern`] if and only if this method returns true."] # [doc = " Otherwise, an error will be returned."] # [doc = ""] # [doc = " Note that if the DFA is empty, this always returns false."] pub fn starts_for_each_pattern (& self) -> bool { self . st . pattern_len . is_some () } # [doc = " Returns the equivalence classes that make up the alphabet for this DFA."] # [doc = ""] # [doc = " Unless [`dense::Config::byte_classes`] was disabled, it is possible"] # [doc = " that multiple distinct bytes are grouped into the same equivalence"] # [doc = " class if it is impossible for them to discriminate between a match and"] # [doc = " a non-match. This has the effect of reducing the overall alphabet size"] # [doc = " and in turn potentially substantially reducing the size of the DFA's"] # [doc = " transition table."] # [doc = ""] # [doc = " The downside of using equivalence classes like this is that every state"] # [doc = " transition will automatically use this map to convert an arbitrary"] # [doc = " byte to its corresponding equivalence class. In practice this has a"] # [doc = " negligible impact on performance."] pub fn byte_classes (& self) -> & ByteClasses { & self . tt . classes } # [doc = " Returns the memory usage, in bytes, of this DFA."] # [doc = ""] # [doc = " The memory usage is computed based on the number of bytes used to"] # [doc = " represent this DFA."] # [doc = ""] # [doc = " This does **not** include the stack size used up by this DFA. To"] # [doc = " compute that, use `std::mem::size_of::<sparse::DFA>()`."] pub fn memory_usage (& self) -> usize { self . tt . memory_usage () + self . st . memory_usage () } }
    };
}

impl_120!()